SET NOCOUNT ON;
SELECT CONCAT('COL ',CAST(t.name AS nvarchar(200)) COLLATE DATABASE_DEFAULT,'.',CAST(c.name AS nvarchar(200)) COLLATE DATABASE_DEFAULT,' ',CAST(ty.name AS nvarchar(100)) COLLATE DATABASE_DEFAULT,'(',c.max_length,',',c.precision,',',c.scale,') null=',c.is_nullable,' def=',CAST(dc.definition AS nvarchar(300)) COLLATE DATABASE_DEFAULT) FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.default_constraints dc ON dc.parent_object_id=c.object_id AND dc.parent_column_id=c.column_id WHERE t.name<>'__EFMigrationsHistory';
SELECT CONCAT('IDX ',CAST(t.name AS nvarchar(200)) COLLATE DATABASE_DEFAULT,'.',CAST(i.name AS nvarchar(200)) COLLATE DATABASE_DEFAULT,' uniq=',i.is_unique,' filter=',CAST(i.filter_definition AS nvarchar(300)) COLLATE DATABASE_DEFAULT,' cols=',(SELECT STRING_AGG(CAST(c.name AS nvarchar(200)) COLLATE DATABASE_DEFAULT,',') WITHIN GROUP (ORDER BY ic.key_ordinal) FROM sys.index_columns ic JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE ic.object_id=i.object_id AND ic.index_id=i.index_id)) FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id WHERE t.name<>'__EFMigrationsHistory' AND i.name IS NOT NULL;
SELECT CONCAT('FK ',CAST(OBJECT_NAME(parent_object_id) AS nvarchar(200)) COLLATE DATABASE_DEFAULT,'.',CAST(name AS nvarchar(200)) COLLATE DATABASE_DEFAULT,' -> ',CAST(OBJECT_NAME(referenced_object_id) AS nvarchar(200)) COLLATE DATABASE_DEFAULT,' del=',CAST(delete_referential_action_desc AS nvarchar(50)) COLLATE DATABASE_DEFAULT) FROM sys.foreign_keys;
